pwd && python3 - <<'EOF'
import json
raw = json.load(open("input/pr-1583/pr_discussions_raw.json"))
out = json.load(open("outputs/review_replies.json"))
raw_ids = {t["threadId"]: (t["rootCommentId"]) for t in raw["threads"] if t["threadId"]}
import os
ok = True
for r in out["replies"]:
    tid, rid, path = r["threadId"], r["inReplyToId"], r["reply"]
    if tid not in raw_ids:
        print("MISMATCH threadId", tid); ok = False
    if raw_ids[tid] != rid:
        print("MISMATCH inReplyToId", tid, rid, "expected", raw_ids[tid]); ok = False
    if not os.path.isfile(path):
        print("MISSING file", path); ok = False
expected_open = {t["threadId"] for t in raw["threads"] if t["threadId"]}
got = {r["threadId"] for r in out["replies"]}
print("open threaded:", len(expected_open), "replied:", len(got), "missing:", expected_open - got)
print("ALL OK" if ok and expected_open == got else "PROBLEMS")
EOF
ls outputs outputs/review_replies

